(function(){
  var SUPPORTED = window.__EL_LANGS__.map(function(l){return l.code});
  function detect(){
    try{
      var stored = window.ELStore.get('elementsLang');
      if(stored && SUPPORTED.indexOf(stored) !== -1) return stored;
    }catch(e){}
    var nav = (navigator.language || 'de').slice(0,2).toLowerCase();
    return SUPPORTED.indexOf(nav) !== -1 ? nav : 'de';
  }
  window.__EL_LANG__ = detect();
  window.getLang = function(){ return window.__EL_LANG__; };
  window.setLang = function(code){
    if(SUPPORTED.indexOf(code) === -1) return;
    window.__EL_LANG__ = code;
    try{ window.ELStore.set('elementsLang', code); }catch(e){}
    window.applyStaticTranslations();
    if(typeof window.render === 'function') window.render();
  };
  // t(key, vars) — falls back to German, then to the key itself.
  window.t = function(key, vars){
    var dict = window.__EL_I18N__[window.__EL_LANG__] || {};
    var s = dict[key];
    if(s === undefined) s = (window.__EL_I18N__.de || {})[key];
    if(s === undefined) return key;
    if(vars) Object.keys(vars).forEach(function(k){
      s = s.split('{'+k+'}').join(String(vars[k]));
    });
    return s;
  };
  // Translates the static chrome that lives in index.html (header, age gate, footer).
  window.applyStaticTranslations = function(){
    document.documentElement.setAttribute('lang', window.t('html.lang'));
    document.title = window.t('meta.title');
    var md = document.querySelector('meta[name="description"]');
    if(md) md.setAttribute('content', window.t('meta.desc'));
    document.querySelectorAll('[data-i18n]').forEach(function(el){
      el.textContent = window.t(el.getAttribute('data-i18n'));
    });
    document.querySelectorAll('[data-i18n-aria]').forEach(function(el){
      el.setAttribute('aria-label', window.t(el.getAttribute('data-i18n-aria')));
    });
    // Language switcher dropdown: update current label + flag
    var cur = window.__EL_LANG__;
    var label = document.querySelector('[data-lang-current-label]');
    if(label) label.textContent = cur.toUpperCase();
    var flag = document.querySelector('[data-lang-current-flag]');
    var flags = {'de':'🇩🇪','en':'🇬🇧','fr':'🇫🇷'};
    if(flag) flag.textContent = flags[cur] || '';
    document.querySelectorAll('[data-lang-btn]').forEach(function(b){
      var on = b.getAttribute('data-lang-btn') === cur;
      b.classList.toggle('active', on);
      b.setAttribute('aria-selected', on ? 'true' : 'false');
    });
  };
})();

